'use client';

import {
  CreateDesignationRequest,
  UpdateDesignationRequest,
  type DesignationResponse,
} from '@uie/contracts';
import { useState } from 'react';
import { z } from 'zod';
import { FormLayout, TextField } from '@/components/erp';
import { Dialog, DialogContent, DialogDescription, DialogTitle } from '@/components/ui/dialog';
import { terminology } from '@/config/terminology';
import { apiRequest, messageForApiError } from '@/lib/api/client';
import * as toast from '@/lib/toast';

// The code (DSG-0001) is generated by the API, so the form only has the name.
const schema = z.object({
  name: z.string().trim().min(1, terminology.validation.required).max(100),
});

type DesignationFormValues = z.infer<typeof schema>;

export interface DesignationDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  /** Present when editing an existing designation. */
  designation?: DesignationResponse;
  onSaved: () => void;
}

export function DesignationDialog({
  open,
  onOpenChange,
  designation,
  onSaved,
}: DesignationDialogProps) {
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const isEdit = designation !== undefined;

  // Defaults are only read when the form mounts (the dialog is keyed by designation id).
  const [defaults] = useState<DesignationFormValues>(() => ({ name: designation?.name ?? '' }));

  async function handleSubmit(values: DesignationFormValues): Promise<void> {
    setErrorMessage(null);

    const checked = isEdit
      ? UpdateDesignationRequest.safeParse(values)
      : CreateDesignationRequest.safeParse(values);

    if (!checked.success) {
      setErrorMessage(terminology.apiErrors.VALIDATION_ERROR);
      return;
    }

    const result = isEdit
      ? await apiRequest('PATCH', `/api/designations/${designation.id}`, checked.data)
      : await apiRequest('POST', '/api/designations', checked.data);

    if (!result.ok) {
      setErrorMessage(messageForApiError(result.code));
      return;
    }

    toast.success(isEdit ? terminology.designations.updated : terminology.designations.created);
    onOpenChange(false);
    onSaved();
  }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent>
        <div className="mb-3 space-y-1">
          <DialogTitle>
            {isEdit ? terminology.designations.editTitle : terminology.designations.addTitle}
          </DialogTitle>
          <DialogDescription className="text-sm text-muted-foreground">
            {isEdit ? designation.code : terminology.designations.codeAutoHint}
          </DialogDescription>
        </div>
        {errorMessage === null ? null : (
          <p role="alert" className="mb-3 text-sm text-danger">
            {errorMessage}
          </p>
        )}
        <FormLayout<DesignationFormValues>
          schema={schema}
          defaultValues={defaults}
          onSubmit={handleSubmit}
          onCancel={() => onOpenChange(false)}
        >
          <div className="grid gap-4">
            <TextField<DesignationFormValues>
              name="name"
              label={terminology.designations.fieldName}
              description={terminology.designations.fieldNameHint}
              required
            />
          </div>
        </FormLayout>
      </DialogContent>
    </Dialog>
  );
}
